public class MethodListerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("methodNames(Sample.class)", "[alpha, beta, gamma]",
                String.valueOf(MethodLister.methodNames(Sample.class)));
        check("methodNames(Tiny.class) is sorted", "[ant, zed]",
                String.valueOf(MethodLister.methodNames(Tiny.class)));
        check("methodNames(Bare.class) -- no methods", "[]",
                String.valueOf(MethodLister.methodNames(Bare.class)));
        java.util.List<String> names = MethodLister.methodNames(Sample.class);
        check("Sample declares 3 methods", 3, names == null ? null : names.size());
        java.util.List<String> tiny = MethodLister.methodNames(Tiny.class);
        check("first Tiny name alphabetically", "ant",
                (tiny == null || tiny.isEmpty()) ? null : tiny.get(0));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

